      { name: "\u5BFC\u5F39\u9A71\u9010\u8230", code: "HOSTILE / D-04", kind: 0, pos: [-195, 55, -710], scale: 2.5, hp: 100, respawn: 0, heading: -0.48, velocity: [0, 0, 0], seed: 1 },
      { name: "\u4FA7\u7FFC\u62A4\u822A\u8230", code: "HOSTILE / F-08", kind: 2, pos: [330, 64, -350], scale: 2.2, hp: 100, respawn: 0, heading: 0.58, velocity: [0, 0, 0], seed: 2 }
